using System.Security.Cryptography;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json.Serialization;
using Aegis.Configuration.Application;
using Aegis.Configuration.Domain;
using Aegis.Configuration.Infrastructure;
using Common.Secrets;
WebApplicationBuilder builder=WebApplication.CreateBuilder(args);builder.Services.ConfigureHttpJsonOptions(o=>o.SerializerOptions.Converters.Add(new JsonStringEnumConverter()));string contractDirectory=builder.Configuration["AegisConfiguration:ContractDirectory"]??Path.Combine(builder.Environment.ContentRootPath,"contracts");string instructionDirectory=builder.Configuration["AegisConfiguration:InstructionDirectory"]??Path.GetFullPath(Path.Combine(builder.Environment.ContentRootPath,"..","..","instruction-packs"));builder.Services.AddCommonSecrets(builder.Configuration);DirectoryContractStore contractStore=new(contractDirectory);builder.Services.AddSingleton<IConfigurationContractStore>(contractStore);builder.Services.AddSingleton<IConfigurationContractRegistrationStore>(contractStore);builder.Services.AddSingleton(new InstructionPackCatalog(instructionDirectory));builder.Services.AddSingleton<ConfigurationEvaluator>();builder.Services.AddSingleton<CommissioningService>();builder.Services.AddSingleton<CommissioningReportRenderer>();builder.Services.AddSingleton<ContractValidator>();WebApplication app=builder.Build();
app.MapGet("/",async(IConfigurationContractStore store,ConfigurationEvaluator evaluator,CancellationToken ct)=>{var contracts=await store.LoadAllAsync(ct);var rows=new List<(ApplicationConfigurationContract Contract,ConfigurationEvaluation Evaluation)>();foreach(var c in contracts.OrderBy(x=>x.DisplayName))rows.Add((c,await evaluator.EvaluateAsync(c,ct)));string cards=rows.Count==0?"<section class='panel empty'><h2>NO APPLICATIONS REGISTERED</h2><p>START AN APPLICATION TO PUBLISH ITS CONFIGURATION CONTRACT.</p></section>":string.Join("",rows.Select(x=>RenderApplication(x.Contract,x.Evaluation)));return Html(Page("Applications","APPLICATIONS // CONFIGURATION REGISTRY",cards,"applications"));});
app.MapGet("/applications/{applicationId}",async(string applicationId,IConfigurationContractStore store,ConfigurationEvaluator evaluator,CancellationToken ct)=>{var c=(await store.LoadAllAsync(ct)).FirstOrDefault(x=>string.Equals(x.ApplicationId,applicationId,StringComparison.OrdinalIgnoreCase));if(c is null)return Results.NotFound();return Html(Page(c.DisplayName,$"APPLICATIONS // {E(c.DisplayName)}",RenderApplication(c,await evaluator.EvaluateAsync(c,ct),true),"applications"));});
app.MapGet("/runbooks",async(IConfigurationContractStore store,CancellationToken ct)=>{var contracts=await store.LoadAllAsync(ct);string body=contracts.Count==0?"<section class='panel empty'><h2>NO RUNBOOKS AVAILABLE</h2></section>":"<section class='panel'><div class='sectiontitle'>CONFIGURATION RUNBOOKS</div><div class='runbooklist'>"+string.Join("",contracts.OrderBy(x=>x.DisplayName).Select(x=>$"<a class='btn' href='/runbooks/{Uri.EscapeDataString(x.ApplicationId)}'>{E(x.DisplayName)} <span class='muted'>// {E(x.Version)}</span></a>"))+"</div></section>";return Html(Page("Runbooks","RUNBOOKS",body,"runbooks"));});
app.MapGet("/runbooks/{applicationId}",async(string applicationId,CommissioningService service,InstructionPackCatalog packs,CommissioningReportRenderer renderer,CancellationToken ct)=>{var s=(await service.EvaluateAllAsync(ct)).FirstOrDefault(x=>string.Equals(x.ApplicationId,applicationId,StringComparison.OrdinalIgnoreCase));if(s is null)return Results.NotFound();string markdown=renderer.RenderMarkdown(s,await packs.FindAsync(s.ApplicationId,s.ApplicationVersion,ct));return Html(Page("Runbook",$"APPLICATIONS // {E(s.ApplicationId)} // RUNBOOK",$"<section class='panel runbook'><div class='runhead'><div><h2>{E(s.ApplicationId)} CONFIGURATION RUNBOOK</h2><div class='muted'>VERSION {E(s.ApplicationVersion)}</div></div><button class='btn' onclick='window.print()'>PRINT / SAVE PDF</button></div><pre>{E(markdown)}</pre></section>","runbooks"));});
app.MapPost("/api/contracts/register",async(ApplicationConfigurationContract contract,HttpContext context,IConfigurationContractRegistrationStore store,ContractValidator validator,ISecretProvider secrets,CancellationToken ct)=>{var v=validator.Validate(contract);if(!v.IsValid)return Results.BadRequest(v);if(!DirectoryContractStore.IsSafeApplicationId(contract.ApplicationId))return Results.BadRequest(new{error="ApplicationId may contain only letters, digits, '.', '-' and '_'."});string supplied=context.Request.Headers["X-Configuration-Registration-Key"].FirstOrDefault()??"";string? expected=await secrets.GetAsync($"configuration/registration/{contract.ApplicationId}",ct);if(string.IsNullOrWhiteSpace(expected)||!FixedTimeEquals(supplied,expected))return Results.Unauthorized();try{return Results.Ok(await store.RegisterAsync(contract,ct));}catch(InvalidDataException ex){return Results.BadRequest(new{error=ex.Message});}});app.MapGet("/api/contracts",async(IConfigurationContractStore store,CancellationToken ct)=>Results.Ok(await store.LoadAllAsync(ct)));app.MapGet("/api/report/{applicationId}",async(string applicationId,CommissioningService service,InstructionPackCatalog packs,CommissioningReportRenderer renderer,CancellationToken ct)=>{var s=(await service.EvaluateAllAsync(ct)).FirstOrDefault(x=>string.Equals(x.ApplicationId,applicationId,StringComparison.OrdinalIgnoreCase));return s is null?Results.NotFound():Results.Text(renderer.RenderMarkdown(s,await packs.FindAsync(s.ApplicationId,s.ApplicationVersion,ct)),"text/markdown");});app.MapPost("/api/contracts/validate",(ApplicationConfigurationContract c,ContractValidator v)=>Results.Ok(v.Validate(c)));app.MapGet("/health",()=>Results.Ok(new{status="healthy",service="Aegis.Configuration",displayName="System Configuration"}));app.Run();
static IResult Html(string v)=>Results.Content(v,"text/html");static string E(string? v)=>HtmlEncoder.Default.Encode(v??"");static bool FixedTimeEquals(string l,string r){byte[] a=Encoding.UTF8.GetBytes(l),b=Encoding.UTF8.GetBytes(r);return a.Length==b.Length&&CryptographicOperations.FixedTimeEquals(a,b);}static string Active(string c,string i)=>c==i?" active":"";
static string Css()=>""":root{--bg:#000;--ink:#f7f4ee;--peach:#ff9966;--orange:#ff9900;--vio:#9999ff;--lav:#cc99cc;--blue:#99ccff;--sand:#ffcc99;--green:#99cc99;--yellow:#ffcc66;--red:#cc6666}*{box-sizing:border-box}body{margin:0;background:#000;color:var(--ink);font:700 14px/1.4 Arial,sans-serif;letter-spacing:.03em}a{color:inherit;text-decoration:none}.shell{min-height:100vh;padding:10px;display:grid;grid-template-columns:180px 1fr;grid-template-rows:96px 1fr;gap:0 10px}.elbow{background:var(--peach);border-radius:52px 0 0 0;position:relative}.elbow:after{content:"";position:absolute;right:0;bottom:0;width:48px;height:46px;background:#000;border-radius:24px 0 0 0}.mast{background:var(--peach);color:#000;border-radius:0 32px 32px 0;padding:34px 18px 8px;text-align:right}.mast h1{margin:0;font-size:clamp(27px,4vw,48px)}.rail{background:linear-gradient(var(--peach) 0 19%,#000 19% 21%,var(--orange) 21% 38%,#000 38% 40%,var(--blue) 40% 57%,#000 57% 59%,var(--vio) 59% 76%,#000 76% 78%,var(--lav) 78%);border-radius:0 0 0 48px;padding-top:18px}.rail a{display:block;background:#000;margin:9px 0 0 22px;padding:9px;color:var(--sand);font-size:11px}.rail a.active{background:var(--sand);color:#000;border-radius:18px 0 0 18px}.main{padding:15px 4px}.bands{display:grid;grid-template-columns:1.5fr .5fr .3fr;gap:7px}.band{height:25px;border-radius:13px;background:var(--orange);color:#000;padding:5px 12px;font-size:11px}.band:nth-child(2){background:var(--blue)}.band:nth-child(3){background:var(--vio)}.crumb{margin:14px 0;color:var(--sand)}.panel{border-top:11px solid var(--blue);border-right:2px solid var(--blue);border-bottom:2px solid var(--blue);margin:12px 0;padding:14px;background:#060606}.appgrid{display:grid;grid-template-columns:1.4fr .7fr .7fr;gap:12px}.appgrid>div{padding:10px}.appgrid h2{font-size:25px;margin:0 0 8px}.complete,.ok{color:var(--green)}.incomplete{color:var(--yellow)}.missing{color:var(--red)}.muted,p,small{color:#aaa}dl{display:grid;grid-template-columns:140px 1fr;gap:4px}dt{color:var(--blue)}dd{margin:0}.actions{display:grid;gap:8px;align-content:start}.btn{display:block;background:var(--vio);color:#000;border:0;border-radius:20px;padding:10px 14px;text-align:right;font-weight:900}.sectiontitle{margin-top:14px;padding:7px 12px;background:var(--orange);color:#000;border-radius:15px 15px 0 0;font-weight:900}.tr{display:grid;grid-template-columns:1.5fr .6fr 1fr .7fr 1fr 1fr;border-top:1px solid #333}.tr>div{padding:9px;overflow-wrap:anywhere}.thead{background:var(--lav);color:#000;font-weight:900}.empty,.runbook{padding:22px}.runbook pre{white-space:pre-wrap;overflow-wrap:anywhere}.runbooklist{display:grid;gap:8px;padding:12px}@media(max-width:850px){.appgrid{grid-template-columns:1fr 1fr}.actions{grid-column:1/-1}.tr{grid-template-columns:1.4fr .7fr 1fr .7fr}.tr>div:nth-child(5),.tr>div:nth-child(6){display:none}}@media(max-width:620px){.shell{grid-template-columns:68px 1fr;grid-template-rows:74px 1fr}.mast{padding-top:25px}.mast h1{font-size:22px}.rail a{font-size:0;height:30px;margin-left:10px}.appgrid{grid-template-columns:1fr}.actions{grid-column:auto}.thead{display:none}.tr{display:block;border:1px solid #333;margin:7px 0}.tr>div{display:block!important;padding:4px}.elbow:after{width:26px;height:32px}}@media print{.rail,.elbow,.mast,.bands{display:none}.shell{display:block}.panel{border:0}}""";
static string Page(string title,string crumb,string content,string active)=>"<!doctype html><html><head><title>"+E(title)+" · System Configuration</title><meta name='viewport' content='width=device-width,initial-scale=1'><style>"+Css()+"</style></head><body><div class='shell'><div class='elbow'></div><header class='mast'><h1>SYSTEM CONFIGURATION</h1></header><aside class='rail'><a class='"+Active(active,"applications")+"' href='/'>APPLICATIONS</a><a class='"+Active(active,"runbooks")+"' href='/runbooks'>RUNBOOKS</a><a href='/api/contracts'>CONTRACTS</a></aside><main class='main'><div class='bands'><div class='band'>AEGIS CONFIGURATION CONTROL</div><div class='band'>REGISTRY</div><div class='band'>READY</div></div><div class='crumb'>"+crumb+"</div>"+content+"</main></div></body></html>";
static string RenderApplication(ApplicationConfigurationContract c,ConfigurationEvaluation e,bool detailsOnly=false){int required=c.Requirements.Count(x=>x.Required),rc=e.Requirements.Count(x=>x.Required&&x.State==ConfigurationState.Configured),optional=c.Requirements.Count(x=>!x.Required),oc=e.Requirements.Count(x=>!x.Required&&x.State==ConfigurationState.Configured);bool complete=e.IsComplete;string id=Uri.EscapeDataString(c.ApplicationId);string reqs=string.Join("",e.Requirements.Select(r=>$"<div class='tr'><div><b>{E(r.DisplayName)}</b><small>{E(r.Purpose)}</small></div><div>{(r.Required?"REQUIRED":"OPTIONAL")}</div><div>{E(r.Sensitive?"PROTECTED / NOT DISPLAYED":r.SafeDisplayValue??(r.State==ConfigurationState.Configured?"CONFIGURED":"NOT CONFIGURED"))}</div><div class='{(r.State==ConfigurationState.Missing?"missing":"ok")}'>{E(r.State.ToString()).ToUpperInvariant()}</div><div>{E(r.Example)}</div><div>{E(r.Message)}</div></div>"));string actions=detailsOnly?$"<a class='btn' href='/runbooks/{id}'>VIEW RUNBOOK →</a><a class='btn' href='/'>BACK →</a>":$"<a class='btn' href='/applications/{id}'>VIEW CONFIGURATION →</a><a class='btn' href='/runbooks/{id}'>RUNBOOK →</a>";string registered=c.LastRegisteredAtUtc?.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss zzz")??"LEGACY / NOT YET RE-REGISTERED";return $"<section class='panel'><div class='appgrid'><div><h2>{E(c.DisplayName).ToUpperInvariant()}</h2><p>{E(c.Description??"Registered application")}</p><dl><dt>APPLICATION ID</dt><dd>{E(c.ApplicationId)}</dd><dt>VERSION</dt><dd>{E(c.Version)}</dd><dt>SITE</dt><dd>{E(c.SiteId??"—")}</dd><dt>INSTANCE</dt><dd>{E(c.InstanceId??"—")}</dd><dt>LAST REGISTRATION</dt><dd>{E(registered)}</dd></dl></div><div><h2 class='{(complete?"complete":"incomplete")}'>{(complete?"✓ COMPLETE":"● INCOMPLETE")}</h2><p>{rc}/{required} REQUIRED // {oc}/{optional} OPTIONAL</p></div><div class='actions'>{actions}</div></div><div class='sectiontitle'>CONFIGURATION REQUIREMENTS</div><div class='table'><div class='tr thead'><div>SETTING / PURPOSE</div><div>REQUIREMENT</div><div>CURRENT VALUE</div><div>STATUS</div><div>EXAMPLE</div><div>NOTES</div></div>{reqs}</div></section>";}
